BEGIN;
CREATE TEMP TABLE r (id uuid PRIMARY KEY, status text, done timestamptz);
INSERT INTO r SELECT gen_random_uuid(), 'succeeded', NULL FROM generate_series(1,5);
-- force the IN-subquery to be the rescanned inner side of a nested loop
SET LOCAL enable_hashjoin = off; SET LOCAL enable_mergejoin = off; SET LOCAL enable_material = off;
EXPLAIN (COSTS OFF) UPDATE r SET done = now() WHERE id IN (SELECT id FROM r WHERE status='succeeded' AND done IS NULL ORDER BY id LIMIT 2 FOR UPDATE SKIP LOCKED);
WITH c AS (UPDATE r SET done = now() WHERE id IN (SELECT id FROM r WHERE status='succeeded' AND done IS NULL ORDER BY id LIMIT 2 FOR UPDATE SKIP LOCKED) RETURNING 1) SELECT count(*) AS claimed_in FROM c;
UPDATE r SET done = NULL;
WITH pick AS MATERIALIZED (SELECT id FROM r WHERE status='succeeded' AND done IS NULL ORDER BY id LIMIT 2 FOR UPDATE SKIP LOCKED),
c AS (UPDATE r SET done = now() FROM pick WHERE r.id = pick.id RETURNING 1) SELECT count(*) AS claimed_cte FROM c;
ROLLBACK;
EOF
